# owner: platform
"""Absence notices for parents."""

from datetime import date
from typing import List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

# ---
def check_marks_belong(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks recorded for some other student."""
    for mark in marks:
        if mark.student_id != student.student_id:
            other_id = mark.student_id
            raise ValueError(f"mark belongs to {other_id}")

# ---
def require_absences(dates: List[date]) -> None:
    """Refuse to build a notice when nothing was missed."""
    if not dates:
        raise ValueError("no absences to write about")

# ---
def absent_dates(
    student: Student, marks: List[Mark]
) -> List[date]:
    """Absent days, oldest first."""
    check_marks_belong(student, marks)
    dates = days_missed(marks)
    require_absences(dates)
    return dates

# ---
def format_day(when: date) -> str:
    """Spelled-out date such as September 1, 2026."""
    return f"{when:%B} {when.day}, {when.year}"

# ---
def join_dates(dates: List[date]) -> str:
    """Dates joined by semicolons, not commas."""
    return "; ".join(format_day(when) for when in dates)

# ---
def render_notice(
    student: Student, dates: List[date]
) -> str:
    """Notice sentence naming the student and the dates."""
    name = f"{student.first_name} {student.last_name}"
    noun = "day" if len(dates) == 1 else "days"
    text = f"{name} was absent on {len(dates)} {noun}"
    return f"Dear parent, {text}: {join_dates(dates)}."

# ---
def build_absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Notice text for the absent days of one student."""
    dates = absent_dates(student, marks)
    return render_notice(student, dates)

after.tests/test_notices.py:
# owner: platform
import unittest
from datetime import date

from rosterkit import notices
from rosterkit.models import Mark, Student

SEFA = Student("1001", "Quillon", "Sefa", "A")
OPENING = "Dear parent, Sefa Quillon was absent on "
THREE_DAYS = (
    OPENING + "3 days: September 1, 2026; "
    "September 3, 2026; September 5, 2026."
)
ONE_DAY = OPENING + "1 day: September 4, 2026."

def sept(number):
    return date(2026, 9, number)

def mark(number, status, student_id="1001"):
    return Mark(student_id, sept(number), status)

def absent(number, student_id="1001"):
    return mark(number, "absent", student_id)

def notice(marks):
    return notices.build_absence_notice(SEFA, marks)

class NoticeTests(unittest.TestCase):
    def test_dates_listed_in_order(self):
        marks = [absent(5), absent(1), absent(3)]
        self.assertEqual(notice(marks), THREE_DAYS)

    def test_single_day_uses_singular(self):
        self.assertEqual(notice([absent(4)]), ONE_DAY)

    def test_only_absent_days_count(self):
        marks = [
            mark(1, "present"),
            mark(2, "late"),
            mark(3, "excused"),
            absent(4)
        ]
        self.assertEqual(notice(marks), ONE_DAY)

    def test_mark_for_another_student_raises(self):
        marks = [absent(1), absent(2, student_id="1002")]
        with self.assertRaises(ValueError):
            notice(marks)

    def test_no_absences_raises(self):
        with self.assertRaises(ValueError):
            notice([mark(1, "present")])

    def test_no_marks_raises(self):
        with self.assertRaises(ValueError):
            notice([])

    def test_format_day_spells_out_month(self):
        text = notices.format_day(sept(1))
        self.assertEqual(text, "September 1, 2026")
